package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"
)

// TokenBucket implements a distributed rate limiter for K8s pod replicas.
// Each pod maintains a local bucket that syncs with a shared state periodically.
type TokenBucket struct {
	mu        sync.Mutex
	tokens    int64
	maxTokens int64
	refillRate int64
	lastRefill time.Time
}

type TransferRequest struct {
	FromAccount string  `json:"from_account"`
	ToAccount   string  `json:"to_account"`
	Amount      float64 `json:"amount"`
	IdempotencyKey string `json:"idempotency_key"`
}

type AccountStore struct {
	mu       sync.RWMutex
	balances map[string]float64
}

type IdempotencyStore struct {
	mu   sync.RWMutex
	keys map[string]bool
}

var (
	accounts = &AccountStore{
		balances: map[string]float64{
			"alice": 1000.0,
			"bob":   500.0,
			"carol": 750.0,
		},
	}
	idempotency = &IdempotencyStore{
		keys: make(map[string]bool),
	}
	rateLimiter = &TokenBucket{
		tokens:     100,
		maxTokens:  100,
		refillRate: 10,
		lastRefill: time.Now(),
	}
)

func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.lastRefill)
	refill := int64(elapsed.Seconds()) * tb.refillRate
	tb.tokens += refill
	if tb.tokens > tb.maxTokens {
		tb.tokens = tb.maxTokens
	}
	tb.lastRefill = now

	if tb.tokens > 0 {
		tb.tokens--
		return true
	}
	return false
}

func (s *IdempotencyStore) CheckAndSet(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.keys[key] {
		return false // already processed
	}
	s.keys[key] = true
	return true
}

func (s *AccountStore) GetBalance(account string) (float64, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	bal, ok := s.balances[account]
	return bal, ok
}

func (s *AccountStore) Transfer(from, to string, amount float64) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	fromBal, ok := s.balances[from]
	if !ok {
		return fmt.Errorf("account %s not found", from)
	}
	toBal, ok := s.balances[to]
	if !ok {
		return fmt.Errorf("account %s not found", to)
	}
	if fromBal < amount {
		return fmt.Errorf("insufficient funds")
	}

	s.balances[from] = fromBal - amount
	s.balances[to] = toBal + amount
	return nil
}

func validateTransfer(req TransferRequest) error {
	if req.Amount <= 0 {
		return fmt.Errorf("amount must be positive")
	}
	if req.FromAccount == req.ToAccount {
		return fmt.Errorf("cannot transfer to same account")
	}
	if req.IdempotencyKey == "" {
		return fmt.Errorf("idempotency key required")
	}
	return nil
}

func transferHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !rateLimiter.Allow() {
		http.Error(w, "rate limited", http.StatusTooManyRequests)
		return
	}

	var req TransferRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	if err := validateTransfer(req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Check idempotency to prevent duplicate processing
	if !idempotency.CheckAndSet(req.IdempotencyKey) {
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "already_processed"})
		return
	}

	// Execute transfer atomically - balance check is inside the lock
	if err := accounts.Transfer(req.FromAccount, req.ToAccount, req.Amount); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "completed"})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	_ = ctx

	mux := http.NewServeMux()
	mux.HandleFunc("/transfer", transferHandler)
	mux.HandleFunc("/health", healthHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Printf("Starting transfer service on :8080")
	if err := server.ListenAndServe(); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
